import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Getting Started with TermBolt","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),n={name:"guide/getting-started.md"};function l(i,e,s,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="getting-started-with-termbolt" tabindex="-1">Getting Started with TermBolt <a class="header-anchor" href="#getting-started-with-termbolt" aria-label="Permalink to &quot;Getting Started with TermBolt&quot;">​</a></h1><p>Welcome to <strong>TermBolt</strong>, an ultra-fast, modern remote access client designed for system administrators, DevOps engineers, and developers managing fleets of remote servers and local workstations.</p><hr><h2 id="📥-installation" tabindex="-1">📥 Installation <a class="header-anchor" href="#📥-installation" aria-label="Permalink to &quot;📥 Installation&quot;">​</a></h2><h3 id="windows-setup-installer" tabindex="-1">Windows (Setup Installer) <a class="header-anchor" href="#windows-setup-installer" aria-label="Permalink to &quot;Windows (Setup Installer)&quot;">​</a></h3><ol><li>Download the latest <strong><code>TermBolt-Setup.exe</code></strong> from the <a href="https://github.com/stahiralijan/termbolt-releases/releases/latest" target="_blank" rel="noreferrer">Official Releases Repository</a>.</li><li>Run the installer wizard. TermBolt will install seamlessly to <code>C:\\Program Files\\TermBolt</code> with desktop and start menu shortcuts.</li><li>Launch <strong>TermBolt</strong> from your desktop or start menu.</li></ol><h3 id="macos-linux" tabindex="-1">macOS &amp; Linux <a class="header-anchor" href="#macos-linux" aria-label="Permalink to &quot;macOS &amp; Linux&quot;">​</a></h3><p><em>macOS (.dmg) and Linux (.AppImage / .deb) packages are currently in development and will be available in upcoming release milestones.</em></p><hr><h2 id="🚀-quick-tour" tabindex="-1">🚀 Quick Tour <a class="header-anchor" href="#🚀-quick-tour" aria-label="Permalink to &quot;🚀 Quick Tour&quot;">​</a></h2><h3 id="_1-connecting-to-a-server" tabindex="-1">1. Connecting to a Server <a class="header-anchor" href="#_1-connecting-to-a-server" aria-label="Permalink to &quot;1. Connecting to a Server&quot;">​</a></h3><ul><li>Click the <strong><code>+</code></strong> button in the Host sidebar to add a new server profile.</li><li>Configure connection parameters: <strong>Protocol</strong> (<code>SSH</code>, <code>Telnet</code>, <code>Local Shell</code>, <code>VNC</code>), <strong>Address / IP</strong>, <strong>Port</strong> (default 22), and <strong>Credentials</strong>.</li><li>Double-click the host card to open a new tab session.</li></ul><h3 id="_2-fast-navigation-via-command-launcher-ctrl-k" tabindex="-1">2. Fast Navigation via Command Launcher (<code>Ctrl+K</code>) <a class="header-anchor" href="#_2-fast-navigation-via-command-launcher-ctrl-k" aria-label="Permalink to &quot;2. Fast Navigation via Command Launcher (`Ctrl+K`)&quot;">​</a></h3><p>Press <kbd>Ctrl</kbd> + <kbd>K</kbd> from anywhere in the application to open the <strong>Fuzzy Quick-Connect Launcher</strong>. Type any keyword, server name, or IP to jump directly into the session.</p><h3 id="_3-in-terminal-search-ctrl-f" tabindex="-1">3. In-Terminal Search (<code>Ctrl+F</code>) <a class="header-anchor" href="#_3-in-terminal-search-ctrl-f" aria-label="Permalink to &quot;3. In-Terminal Search (`Ctrl+F`)&quot;">​</a></h3><p>Search your active scrollback buffer instantly by pressing <kbd>Ctrl</kbd> + <kbd>F</kbd>. Match navigation with <kbd>Enter</kbd> (next) and <kbd>Shift+Enter</kbd> (previous).</p><hr><h2 id="🔒-master-vault-unlock" tabindex="-1">🔒 Master Vault Unlock <a class="header-anchor" href="#🔒-master-vault-unlock" aria-label="Permalink to &quot;🔒 Master Vault Unlock&quot;">​</a></h2><p>On first launch, you will be prompted to set an optional <strong>Master Password</strong> to lock your local credential vault.</p><ul><li>All stored credentials (passwords, private keys, passphrases) are encrypted using <strong>AES-256-GCM</strong> with a <strong>PBKDF2 SHA-256 (100,000 rounds)</strong> derived key.</li><li>If locked, click the lock icon in the top titlebar or press <kbd>Ctrl</kbd> + <kbd>,</kbd> to enter your master key.</li></ul>',20)])])}const g=t(n,[["render",l]]);export{m as __pageData,g as default};
